create table xxcus.xxcmp_doc_verifications (
    verification_id       number generated by default on null as identity minvalue 1 maxvalue 9999999999999999999999999999 increment by
    1 cache 20 noorder nocycle nokeep noscale not null enable,
    case_id               number not null enable,
    attached_document_id  number not null enable,
    verification_status   varchar2(30 byte) not null enable,
    notes                 varchar2(4000 byte),
    created_by            varchar2(255 byte) not null enable,
    creation_date         timestamp(6) not null enable,
    last_updated_by       varchar2(255 byte) not null enable,
    last_update_date      timestamp(6) not null enable,
    last_update_login     varchar2(255 byte),
    object_version_number number default 1 not null enable
);

alter table xxcus.xxcmp_doc_verifications
    add constraint xxcmp_doc_verifications_ck1
        check ( verification_status in ( 'VERIFIED', 'REJECTED', 'EXPIRED' ) ) enable;

alter table xxcus.xxcmp_doc_verifications
    add constraint xxcmp_doc_verifications_pk primary key ( verification_id )
        using index enable;

alter table xxcus.xxcmp_doc_verifications
    add constraint xxcmp_doc_verifications_uk1 unique ( case_id,
                                                        attached_document_id )
        using index enable;


